def solve(inputs: dict) -> float:
    """Compute the final convergent numerator for continued-fraction terms."""
    terms = inputs.get('terms', inputs.get('coefficients', inputs.get('a', inputs.get('continued_fraction'))))
    if terms is None:
        raise KeyError('continued-fraction terms are required')
    p_prevprev, p_prev = 0, 1
    for term in terms:
        p_prevprev, p_prev = p_prev, int(term) * p_prev + p_prevprev
    return float(p_prev)

